script:
(function () {
  'use strict';
  // Individual (solo) 401(k) projection. Each year's contribution is worked out from that year's income:
  // sole proprietor / partner -> IRS Pub. 560 Deduction Worksheet for Self-Employed (steps 1-19): net
  // earnings = profit - deductible half of SE tax; employer profit sharing = plan rate / (1 + plan rate) of
  // net earnings (20% at the 25% maximum), limited with the deferral to $72,000 and to net earnings; the
  // catch-up sits on top. S/C corporation -> deferral from W-2 wages plus plan rate x wages, deferral +
  // employer <= $72,000 and <= wages. Deposits go in monthly and compound monthly at (1 + r)^(1/12) - 1.
  // Limits stay at 2026 amounts in later years (no indexing); the age catch-up follows the age each year.
  // Checked in Node (scratchpad solo401k/tests/engine.test.js + ik.test.js): Pub. 560 (2025) example with
  // 2025 constants (SE deduction $13,596, net earnings $186,404, step 6 $29,750); 2026 $100,000 profit at 40 ->
  // $24,500 + $18,587.05 = $43,087.05; a 10% plan rate -> 10/110 = 9.0909% of net earnings ($8,448.66) and
  // step 6 = $36,000; $400,000 profit at 61 -> $72,000 + $11,250; corporation $100,000 wages -> $49,500;
  // $500/month for 30 years at 7% = $584,726 (same projection convention as 401k-calculator).
  // ---- 2026 constants (tax year 2026) -------------------------------------------------------------
  // Plan limits: IRS Notice 2025-67. SIMPLE higher limits (employers with 25 or fewer employees, SECURE 2.0
  // sec. 117; automatic per Notice 2024-2 when the employer had no other plan in the prior 3 years): Notice
  // 2025-67. SE tax: Schedule SE / IRC 1401-1402; Social Security wage base $184,500 (SSA 2026, same constant
  // as self-employment-tax-calculator). Plan-rate conversion and worksheet: IRS Pub. 560 chapter 5.
  var Y = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit, 401(k) (shared across all your 401(k)/403(b) plans)
    catchUp50: 8000,        // 414(v) catch-up, 401(k), age 50+
    catchUp60to63: 11250,   // 401(k) catch-up for ages 60-63
    annualAdditions: 72000, // 415(c) limit on deferrals + employer money (age catch-up excluded); also SEP cap
    compensation: 360000,   // 401(a)(17) / 408(k)(6)(D)(ii) pay limit for employer contributions
    employerRate: 0.25,     // maximum employer (profit-sharing / SEP) rate: 25% of pay, 20% of net SE earnings
    simple: {
      standard: { deferral: 17000, catchUp50: 4000, catchUp60to63: 5250 },   // 408(p)(2)(E)(i)(III), 414(v)(2)(B)(ii)
      small: { deferral: 18100, catchUp50: 3850, catchUp60to63: 5250 },      // 408(p)(2)(E)(i)(I)-(II), 414(v)(2)(B)(iii)
      matchRate: 0.03       // dollar-for-dollar match up to 3% of pay
    },
    se: { factor: 0.9235, ss: 0.124, med: 0.029, wageBase: 184500, floor: 400 }
  };
  // -------------------------------------------------------------------------------------------------

  function ageCatchUp(age, a50, a60) {
    if (age >= 60 && age <= 63) return a60;
    if (age >= 50) return a50;
    return 0;
  }
  function clamp0(x) { return x > 0 ? x : 0; }

  // Schedule SE: net earnings (line 4/6), SE tax and its deductible half. otherWages = W-2 Social Security
  // wages from a job, which use up part of the Social Security wage base.
  function seTax(profit, otherWages) {
    var line4 = profit > 0 ? profit * Y.se.factor : 0;
    var tax = line4 < Y.se.floor ? 0 : Y.se.ss * Math.min(line4, clamp0(Y.se.wageBase - otherWages)) + Y.se.med * line4;
    return { earnings: line4, tax: tax, half: tax / 2 };
  }

  // Solo 401(k) for a sole proprietor / partner: Pub. 560 Deduction Worksheet for Self-Employed, steps 1-19.
  // planRate = employer contribution rate stated in the plan (max 25%); reduced rate = planRate / (1 + planRate)
  // (Rate Worksheet; not rounded here). wantDeferral = total deferral wanted including catch-up (Infinity = max).
  function soloSoleProp(profit, age, otherWages, otherDeferrals, wantDeferral, planRate) {
    var se = seTax(profit, otherWages);
    var s = { s1: profit, s2: se.half, seTax: se.tax };
    s.s3 = clamp0(profit - se.half);
    s.s4 = planRate / (1 + planRate);
    s.s5 = s.s3 * s.s4;
    s.s6 = Y.compensation * planRate;
    s.s7 = Math.min(s.s5, s.s6);
    s.s8 = Y.annualAdditions;
    var basicRoom = clamp0(Y.deferral - otherDeferrals);
    s.s9 = Math.min(wantDeferral, basicRoom, s.s3);
    s.s10 = s.s8 - s.s9;
    s.s11 = s.s3 - s.s9;
    s.s12 = s.s11 / 2;
    s.s13 = Math.min(s.s7, s.s10, s.s12);
    s.s14 = s.s3 - s.s13;
    s.s15 = Math.min(s.s9, s.s14);
    s.s16 = s.s14 - s.s15;
    s.s17 = s.s9 >= basicRoom ? Math.min(clamp0(wantDeferral - s.s9), ageCatchUp(age, Y.catchUp50, Y.catchUp60to63)) : 0;
    s.s18 = Math.min(s.s16, s.s17);
    s.s19 = s.s13 + s.s15 + s.s18;
    return { deferral: s.s15, catchUp: s.s18, employer: s.s13, total: s.s19, comp: s.s3, steps: s };
  }

  // Solo 401(k) for an S or C corporation owner paid W-2 wages: deferrals come out of wages; the employer
  // adds planRate x wages (wages capped at the pay limit); deferrals + employer <= $72,000 and <= wages.
  function soloCorp(wages, age, otherDeferrals, wantDeferral, planRate) {
    var w = clamp0(wages);
    var deferral = Math.min(wantDeferral, clamp0(Y.deferral - otherDeferrals), w);
    var catchUp = deferral >= clamp0(Y.deferral - otherDeferrals)
      ? Math.min(clamp0(wantDeferral - deferral), ageCatchUp(age, Y.catchUp50, Y.catchUp60to63), w - deferral) : 0;
    var employer = Math.min(planRate * Math.min(w, Y.compensation), Y.annualAdditions - deferral, w - deferral);
    employer = clamp0(employer);
    return { deferral: deferral, catchUp: catchUp, employer: employer, total: deferral + catchUp + employer, comp: w };
  }

  // SEP-IRA: employer contributions only (no deferrals or catch-up).
  function sep(isCorp, income, otherWages) {
    var comp, employer;
    if (isCorp) { comp = clamp0(income); employer = Y.employerRate * Math.min(comp, Y.compensation); }
    else {
      comp = clamp0(income - seTax(income, otherWages).half);
      employer = Math.min(comp * Y.employerRate / (1 + Y.employerRate), Y.compensation * Y.employerRate);
    }
    employer = Math.min(employer, Y.annualAdditions);
    return { deferral: 0, catchUp: 0, employer: employer, total: employer, comp: comp };
  }

  // SIMPLE IRA: salary reduction up to the SIMPLE limit (also inside your 402(g) total), age catch-up, and the
  // 3% dollar-for-dollar match. Self-employed pay = Schedule SE net earnings before contributions (Pub. 560).
  function simpleIra(isCorp, income, age, otherWages, otherDeferrals, small) {
    var L = small ? Y.simple.small : Y.simple.standard;
    var comp = isCorp ? clamp0(income) : seTax(income, otherWages).earnings;
    var room = Math.min(L.deferral, clamp0(Y.deferral - otherDeferrals));
    var deferral = Math.min(room, comp);
    var catchUp = deferral >= room ? Math.min(ageCatchUp(age, L.catchUp50, L.catchUp60to63), comp - deferral) : 0;
    var employer = Math.min(deferral + catchUp, Y.simple.matchRate * comp);
    return { deferral: deferral, catchUp: catchUp, employer: employer, total: deferral + catchUp + employer, comp: comp };
  }

  // p: isCorp, income, growth, age, retireAge, balance, rate, inflation (decimals), defMode, def, planRate,
  //    wages, otherDef.
  function project(p) {
    var years = p.retireAge - p.age, mRate = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.balance, income = p.income, totYou = 0, totEr = 0, rows = [];
    for (var y = 0; y < years; y++) {
      var a = p.age + y, want = p.defMode === 'max' ? Infinity : p.def;
      var c = p.isCorp ? soloCorp(income, a, p.otherDef, want, p.planRate)
                       : soloSoleProp(income, a, p.wages, p.otherDef, want, p.planRate);
      var you = c.deferral + c.catchUp, dep = (you + c.employer) / 12;
      for (var m = 0; m < 12; m++) bal = bal * (1 + mRate) + dep;
      totYou += you; totEr += c.employer;
      rows.push({ age: a, income: income, you: you, employer: c.employer, c: c, balance: bal });
      income = income * (1 + p.growth);
    }
    return { balance: bal, real: bal / Math.pow(1 + p.inflation, years), you: totYou, er: totEr,
             growth: bal - p.balance - totYou - totEr, rows: rows };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function el(id) { return document.getElementById(id); }
  function set(id, t) { el(id).textContent = t; }
  function num(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function update() {
    var isCorp = el('ikType').value === 'corp', defMode = el('ikDefMode').value, erMode = el('ikErMode').value;
    el('ikDefWrap').hidden = defMode !== 'dollar';
    el('ikErWrap').hidden = erMode !== 'rate';
    el('ikWagesWrap').hidden = isCorp;
    set('ikIncomeLabel', isCorp ? 'Your W-2 salary' : 'Net business profit');
    set('ikIncomeCol', isCorp ? 'Salary' : 'Profit');
    set('ikIncomeHint', isCorp ? 'Gross salary from your corporation before 401(k) deferrals. Profit paid out as distributions doesn’t count.'
      : 'Schedule C profit (or partnership earnings) before contributions for yourself.');
    set('ikErHint', isCorp ? 'The employer can contribute up to 25% of your W-2 salary.'
      : 'For the self-employed a 25% plan rate works out to 20% of net earnings after the self-employment tax deduction.');
    set('ikCompLabel', isCorp ? 'W-2 salary counted' : 'Net earnings from self-employment');
    var p = { isCorp: isCorp, income: num('ikIncome', NaN), growth: num('ikGrowth', NaN), age: num('ikAge', NaN),
              retireAge: num('ikRetireAge', NaN), balance: num('ikBalance', NaN), rate: num('ikRate', NaN),
              inflation: num('ikInflation', 0), defMode: defMode, def: defMode === 'dollar' ? num('ikDef', NaN) : 0,
              planRate: erMode === 'rate' ? num('ikEr', NaN) : 25, wages: isCorp ? 0 : num('ikWages', 0),
              otherDef: num('ikOtherDef', 0) };
    var error = el('ikError');
    var bad = ['income', 'growth', 'age', 'retireAge', 'balance', 'rate', 'inflation', 'def', 'planRate', 'wages', 'otherDef']
                .some(function (k) { return isNaN(p[k]); }) ||
              p.income < 0 || p.income > 100000000 || p.growth < 0 || p.growth > 20 || p.age !== Math.round(p.age) ||
              p.retireAge !== Math.round(p.retireAge) || p.age < 16 || p.age > 99 || p.retireAge <= p.age || p.retireAge > 100 ||
              p.balance < 0 || p.rate < 0 || p.rate > 30 || p.inflation < 0 || p.inflation > 20 || p.def < 0 ||
              p.planRate < 0 || p.planRate > 25 || p.wages < 0 || p.otherDef < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a non-negative income, growth up to 20%, whole-number ages from 16 to 99 with retirement above ' +
                          'your age (up to 100), a return up to 30%, a plan rate from 0 to 25% and non-negative amounts.';
      return;
    }
    ['growth', 'rate', 'inflation', 'planRate'].forEach(function (k) { p[k] = p[k] / 100; });
    var r = project(p);
    var maxP = Object.assign({}, p, { defMode: 'max', planRate: Y.employerRate });
    var maxR = project(maxP);
    var f = r.rows[0].c, fm = maxR.rows[0].c;
    set('ikRetireLabel', 'Balance at age ' + p.retireAge);
    set('ikFuture', fmt(r.balance)); set('ikReal', fmt(r.real)); set('ikYouTotal', fmt(r.you)); set('ikErTotal', fmt(r.er));
    set('ikGrowthTotal', fmt(r.growth)); set('ikYear', fmt(f.total));
    set('ikComp', fmt(f.comp)); set('ikYrDef', fmt(f.deferral)); set('ikYrCatch', fmt(f.catchUp)); set('ikYrEr', fmt(f.employer));
    set('ikYrTotal', fmt(f.total)); set('ikYrMax', fmt(fm.total));
    var gap = fm.total - f.total;
    set('ikGap', fm.total < 0.5 ? 'With no ' + (isCorp ? 'salary' : 'net self-employment earnings') + ' you can’t contribute this year.'
      : gap > 0.5 ? 'You are putting in ' + fmt(gap) + ' less than the ' + Y.year + ' maximum of ' + fmt(fm.total) +
        '. Contributing the most allowed every year would give about ' + fmt(maxR.balance) + ' at ' + p.retireAge + '.'
      : 'You are contributing the most the ' + Y.year + ' limits allow at this income.');
    var body = el('ikSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, fmt(row.income), fmt(row.you), fmt(row.employer), fmt(row.balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('ikForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
